#include <Arduino.h>
#include <Servo.h>
const int SHCP_PIN = A2;  
const int STCP_PIN = A1;  
const int DS_PIN = A0;    
const int POT1_PIN = A3;  
const int POT2_PIN = A4;  
Servo servo1;
Servo servo2;
Servo servo3;
const byte segmentCodes[] = {
  0b11000000, 
  0b11111001, 
  0b10100100, 
  0b10110000, 
  0b10011001, 
  0b10010010, 
  0b10000010, 
  0b11111000, 
  0b10000000, 
  0b10010000  
};

void setup();
void loop();
void displayNumberOn7Segment(int number);
void setup() {
  pinMode(SHCP_PIN, OUTPUT);
  pinMode(STCP_PIN, OUTPUT);
  pinMode(DS_PIN, OUTPUT);
  servo1.attach(2);  
  servo2.attach(3);  
  servo3.attach(4);  
}
void loop() {
  int pot1Value = analogRead(POT1_PIN);
  int pot2Value = analogRead(POT2_PIN);
  int displayNumber = map(pot1Value, 0, 1023, 0, 9);
  displayNumberOn7Segment(displayNumber);
  int servo1Angle = map(pot2Value, 0, 1023, 0, 90);
  int servo2Angle = map(pot2Value, 0, 1023, 90, 180);
  int servo3Angle = map(pot2Value, 0, 1023, 180, 270);
  servo1.write(servo1Angle);
  servo2.write(servo2Angle);
  servo3.write(servo3Angle);
  delay(20);  
}
void displayNumberOn7Segment(int number) {
  if (number < 0 || number > 9) return;  
  byte segmentCode = segmentCodes[number];
  shiftOut(DS_PIN, SHCP_PIN, MSBFIRST, segmentCode);
  digitalWrite(STCP_PIN, HIGH);
  digitalWrite(STCP_PIN, LOW);
}
